export function normalizeLanguage(value) { return value === 'zh-CN' ? 'zh-CN' : 'en'; }
const escape = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const pattern = new RegExp(Object.keys(messages).sort((a,b)=>b.length-a.length).map(escape).join('|'), 'g');
export function translateText(text, language = 'en') {
  if (normalizeLanguage(language) === 'zh-CN') return text;
  return text.replace(pattern, match => messages[match]);
}
export function installLanguageUI(document, storage) {
  const selector = document.getElementById('language');
  let language = 'en';
  try { language = normalizeLanguage(storage?.getItem('guardian.language')); } catch {}
  const originals = new WeakMap();
  function localizeText(node) {
    if (node.parentElement?.closest('script,style,pre,code,textarea,[data-no-translate]')) return;
    const previous = originals.get(node);
    const source = previous && node.data === previous.output ? previous.source : node.data;
    const output = translateText(source, language);
    originals.set(node, {source, output});
    if (node.data !== output) node.data = output;
  }
  function apply() {
    observer.disconnect();
    document.documentElement.lang = language;
    selector.value = language;
    const walker = document.createTreeWalker(document.body, 4);
    while (walker.nextNode()) localizeText(walker.currentNode);
    for (const element of document.querySelectorAll('[placeholder],[aria-label],[title]')) {
      let values = originals.get(element);
      if (!values) originals.set(element, values = {});
      for (const attribute of ['placeholder','aria-label','title']) {
        if (!element.hasAttribute(attribute)) continue;
        const current = element.getAttribute(attribute), previous = values[attribute];
        const source = previous && current === previous.output ? previous.source : current;
        const output = translateText(source, language);
        values[attribute] = {source, output};
        if (current !== output) element.setAttribute(attribute, output);
      }
    }
    observer.observe(document.body, {subtree:true, childList:true, characterData:true});
  }
  const observer = new MutationObserver(apply);
  selector.addEventListener('change', () => {
    language = normalizeLanguage(selector.value);
    try { storage?.setItem('guardian.language', language); } catch {}
    apply();
  });
  apply();
  return {get language(){return language;}, refresh:apply};
}
